function formatDateNL(iso) {
  const d = new Date(iso);
  return d.toLocaleDateString("nl-NL", { weekday: "long", day: "numeric", month: "long" }) +
    " · " + d.toLocaleTimeString("nl-NL", { hour: "2-digit", minute: "2-digit" });
}
function formatDateShort(iso) {
  return new Date(iso).toLocaleDateString("nl-NL", { day: "numeric", month: "short", year: "numeric" });
}
function useCountdown(targetIso) {
  const [left, setLeft] = useState(null);
  useEffect(() => {
    if (!targetIso) return;
    const tick = () => {
      const diff = new Date(targetIso).getTime() - Date.now();
      setLeft(diff > 0 ? diff : 0);
    };
    tick();
    const id = setInterval(tick, 1000 * 30);
    return () => clearInterval(id);
  }, [targetIso]);
  if (left === null) return "—";
  const days = Math.floor(left / (1000 * 60 * 60 * 24));
  const hours = Math.floor((left / (1000 * 60 * 60)) % 24);
  const mins = Math.floor((left / (1000 * 60)) % 60);
  if (left <= 0) return "Nu";
  return `${days}d ${hours}u ${mins}m`;
}
function deadlinePassed(match) {
  const info = matchTypeInfo(match.category);
  const deadline = new Date(match.match_date).getTime() - info.deadlineHours * 60 * 60 * 1000;
  return Date.now() > deadline;
}
function deadlineLabel(match) {
  const info = matchTypeInfo(match.category);
  const deadline = new Date(new Date(match.match_date).getTime() - info.deadlineHours * 60 * 60 * 1000);
  return deadline.toLocaleDateString("nl-NL", { day: "numeric", month: "short" }) +
    " " + deadline.toLocaleTimeString("nl-NL", { hour: "2-digit", minute: "2-digit" });
}

const SESSION_KEY = "tott_session_player_id";


function useMobileViewportLock() {
  useEffect(() => {
    let meta = document.querySelector('meta[name="viewport"]');
    if (!meta) {
      meta = document.createElement('meta');
      meta.setAttribute('name', 'viewport');
      document.head.appendChild(meta);
    }
    meta.setAttribute(
      'content',
      'width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover'
    );

    const preventGesture = (event) => event.preventDefault();
    document.addEventListener('gesturestart', preventGesture, { passive: false });
    document.addEventListener('gesturechange', preventGesture, { passive: false });
    document.addEventListener('gestureend', preventGesture, { passive: false });

    return () => {
      document.removeEventListener('gesturestart', preventGesture);
      document.removeEventListener('gesturechange', preventGesture);
      document.removeEventListener('gestureend', preventGesture);
    };
  }, []);
}
const LOCAL_POSTS_KEY = "tott_local_club_posts_v1";
const LOCAL_BRANDING_KEY = "tott_local_branding_correct_original_logo_v2";
const LOCAL_VIDEOS_KEY = "tott_local_match_videos_v1";

const ROLE_LABELS = { admin: "Admin", begeleider: "Begeleider", speler: "Speler" };
const roleLabel = (role) => ROLE_LABELS[role] || "Speler";
const canPostUpdates = (player) => player?.role === "admin" || player?.role === "begeleider";
const isFinancialContributor = (player) => player?.role !== "begeleider";

const DEFAULT_BRANDING = {
  logoUrl: "data:image/png;base64,",
  loginBannerUrl: "",
  dashboardBannerUrl: "",
  sponsorImageUrl: "",
  clubShortName: "FC TOTT",
};

function readLocalJson(key, fallback) {
  if (typeof window === "undefined") return fallback;
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function useLocalJsonState(key, fallback) {
  const [value, setValue] = useState(() => readLocalJson(key, fallback));

  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      window.localStorage.setItem(key, JSON.stringify(value));
    } catch (error) {
      console.warn("Kon clubdata niet opslaan", error);
    }
  }, [key, value]);

  return [value, setValue];
}

function normalizeImages(images = []) {
  return images.map((img) => String(img || "").trim()).filter(Boolean).slice(0, 6);
}

function makePostId() {
  return `post_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}
function makeVideoId() {
  return `video_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}
function getYouTubeId(url = "") {
  const value = String(url || "").trim();
  if (!value) return "";
  try {
    const parsed = new URL(value);
    if (parsed.hostname.includes("youtu.be")) return parsed.pathname.replace("/", "").split("/")[0];
    if (parsed.searchParams.get("v")) return parsed.searchParams.get("v");
    const parts = parsed.pathname.split("/").filter(Boolean);
    const marker = parts.findIndex((part) => ["embed", "shorts", "live"].includes(part));
    if (marker >= 0 && parts[marker + 1]) return parts[marker + 1];
    return parts[0] || "";
  } catch {
    return value;
  }
}
function getYouTubeEmbedUrl(url = "") {
  const id = getYouTubeId(url);
  return id ? `https://www.youtube-nocookie.com/embed/${id}` : "";
}

// ============================================================
// App shell
// ============================================================
const NAV = [
  { key: "overzicht", label: "Overzicht", icon: LayoutDashboard },
  { key: "wedstrijden", label: "Wedstrijden", icon: Calendar },
  { key: "profiel", label: "Profiel", icon: UserCog },
  { key: "updates", label: "Updates", icon: Newspaper },
  { key: "videos", label: "Video's", icon: Video },
  { key: "boetepot", label: "Boetepot", icon: Coins },
  { key: "huisregels", label: "Huisregels", icon: ShieldCheck },
  { key: "financien", label: "Financiën", icon: Wallet },
  { key: "beheer", label: "Beheer", icon: Settings },
];

export default function App() {
  useMobileViewportLock();
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(null);
  const [tab, setTab] = useState("overzicht");
  const swipeStartRef = useRef(null);
  const [route, setRoute] = useState(() => {
    if (typeof window === "undefined") return "public";
    return window.location.pathname.startsWith("/portal") ? "portal" : "public";
  });

  useEffect(() => {
    const onPopState = () => setRoute(window.location.pathname.startsWith("/portal") ? "portal" : "public");
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const goToPortal = () => {
    if (typeof window !== "undefined") {
      window.history.pushState({}, "", "/portal");
      setRoute("portal");
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  const goToPublic = () => {
    if (typeof window !== "undefined") {
      window.history.pushState({}, "", "/");
      setRoute("public");
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  const [players, setPlayers] = useState([]);
  const [matches, setMatches] = useState([]);
  const [rules, setRules] = useState([]);
  const [feeTypes, setFeeTypes] = useState([]);
  const [feePayments, setFeePayments] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [lineups, setLineups] = useState([]);
  const [goals, setGoals] = useState([]);
  const [fineRules, setFineRules] = useState([]);
  const [fines, setFines] = useState([]);

  const [sessionId, setSessionId] = useState(null);
  const [clubPosts, setClubPosts] = useState([]);
  const [matchVideos, setMatchVideos] = useState([]);
  const [clubSponsors, setClubSponsors] = useState([]);
  const [friendlyRequests, setFriendlyRequests] = useState([]);
  const [branding, setBranding] = useState(DEFAULT_BRANDING);
  const [notificationReads, setNotificationReads] = useState([]);

  const syncClubPosts = async (nextOrUpdater) => {
    const next = typeof nextOrUpdater === "function" ? nextOrUpdater(clubPosts) : nextOrUpdater;
    setClubPosts(next);
    try {
      await db.saveClubPosts(next);
    } catch (err) {
      console.error(err);
      alert("Update kon niet worden opgeslagen. Controleer de verbinding en probeer opnieuw.");
    }
  };

  const syncMatchVideos = async (nextOrUpdater) => {
    const next = typeof nextOrUpdater === "function" ? nextOrUpdater(matchVideos) : nextOrUpdater;
    setMatchVideos(next);
    try {
      await db.saveClubVideos(next);
    } catch (err) {
      console.error(err);
      alert("Video kon niet worden opgeslagen. Controleer de verbinding en probeer opnieuw.");
    }
  };

  const syncBranding = async (nextBranding) => {
    const next = { ...DEFAULT_BRANDING, ...(nextBranding || {}) };
    setBranding(next);
    try {
      await db.saveClubBranding(next);
    } catch (err) {
      console.error(err);
      alert("Branding kon niet worden opgeslagen. Controleer de verbinding en probeer opnieuw.");
    }
  };

  const reloadAll = async () => {
    const [p, m, r, ft, fp, att, lu, gl, fr, fn, posts, videos, sharedBranding, sponsors, requests] = await Promise.all([
      db.fetchPlayers(), db.fetchMatches(), db.fetchRules(), db.fetchFeeTypes(),
      db.fetchFeePayments(), db.fetchAttendance(), db.fetchLineups(), db.fetchGoals(),
      db.fetchFineRules(), db.fetchFines(), db.fetchClubPosts(), db.fetchClubVideos(), db.fetchClubBranding(),
      db.fetchClubSponsors(), db.fetchFriendlyMatchRequests(),
    ]);
    setPlayers(p); setMatches(m); setRules(r); setFeeTypes(ft);
    setFeePayments(fp); setAttendance(att); setLineups(lu); setGoals(gl);
    setFineRules(fr); setFines(fn);
    setClubPosts(posts || []); setMatchVideos(videos || []);
    setClubSponsors(sponsors || []); setFriendlyRequests(requests || []);
    setBranding({ ...DEFAULT_BRANDING, ...(sharedBranding || {}) });
    return p;
  };

  useEffect(() => {
    (async () => {
      try {
        const p = await reloadAll();
        const storedId = localStorage.getItem(SESSION_KEY);
        if (storedId && p.some((pl) => pl.id === storedId && pl.active)) {
          setSessionId(storedId);
        }
      } catch (e) {
        console.error(e);
        setLoadError("Het clubportaal is tijdelijk niet bereikbaar.");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const me = players.find((p) => p.id === sessionId);
  const isAdmin = me?.role === "admin";
  const isBegeleider = me?.role === "begeleider";
  const canManageContent = isAdmin || isBegeleider;
  const navItems = NAV.filter((item) => {
    if (item.key === "beheer") return isAdmin;
    if (item.key === "financien") return !isBegeleider || isAdmin;
    return true;
  });

  useEffect(() => {
    if (!me?.id) {
      setNotificationReads([]);
      return;
    }
    db.fetchNotificationReads(me.id)
      .then((rows) => setNotificationReads((rows || []).map((row) => row.notification_key)))
      .catch((err) => console.error("Kon gelezen meldingen niet laden", err));
  }, [me?.id]);

  const markNotificationsRead = async (keys = []) => {
    if (!me?.id || keys.length === 0) return;
    const uniqueKeys = [...new Set(keys.filter(Boolean))];
    setNotificationReads((current) => [...new Set([...current, ...uniqueKeys])]);
    try {
      await Promise.all(uniqueKeys.map((key) => db.markNotificationRead(me.id, key)));
    } catch (err) {
      console.error("Kon meldingen niet als gelezen opslaan", err);
    }
  };

  useEffect(() => {
    if (!me) return;
    if (!navItems.some((item) => item.key === tab)) setTab("overzicht");
  }, [me?.id, isAdmin, isBegeleider, tab]);

  const nextMatch = matches
    .filter((m) => new Date(m.match_date).getTime() > Date.now())
    .sort((a, b) => new Date(a.match_date) - new Date(b.match_date))[0];
  const countdown = useCountdown(nextMatch?.match_date);

  const login = (id) => {
    setSessionId(id);
    localStorage.setItem(SESSION_KEY, id);
  };
  const logout = () => {
    setSessionId(null);
    localStorage.removeItem(SESSION_KEY);
    setTab("overzicht");
  };

  const changeTab = (nextTab) => {
    setTab(nextTab);

    if (typeof window !== "undefined" && window.matchMedia("(max-width: 820px)").matches) {
      window.setTimeout(() => {
        document.querySelector(".dreelio-main")?.scrollIntoView({ behavior: "smooth", block: "start" });
        document.querySelector(`[data-nav-key="${nextTab}"]`)?.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
      }, 80);
    }
  };

  const moveTab = (direction) => {
    const currentIndex = navItems.findIndex((item) => item.key === tab);
    if (currentIndex < 0) return;
    const nextIndex = Math.min(Math.max(currentIndex + direction, 0), navItems.length - 1);
    if (nextIndex !== currentIndex) changeTab(navItems[nextIndex].key);
  };

  const handleSwipeStart = (event) => {
    if (!window.matchMedia("(max-width: 860px)").matches) return;
    const touch = event.touches?.[0];
    if (!touch) return;
    swipeStartRef.current = { x: touch.clientX, y: touch.clientY };
  };

  const handleSwipeEnd = (event) => {
    if (!swipeStartRef.current) return;
    const touch = event.changedTouches?.[0];
    if (!touch) return;
    const deltaX = touch.clientX - swipeStartRef.current.x;
    const deltaY = touch.clientY - swipeStartRef.current.y;
    swipeStartRef.current = null;

    if (Math.abs(deltaX) < 70 || Math.abs(deltaX) < Math.abs(deltaY) * 1.35) return;
    moveTab(deltaX < 0 ? 1 : -1);
  };

  // helper maps for attendance/lineups grouped by match
  const attendanceByMatch = {};
  attendance.forEach((a) => {
    attendanceByMatch[a.match_id] = attendanceByMatch[a.match_id] || {};
    attendanceByMatch[a.match_id][a.player_id] = { status: a.status, reason: a.reason };
  });
  const lineupsByMatch = {};
  lineups.forEach((l) => {
    lineupsByMatch[l.match_id] = lineupsByMatch[l.match_id] || { keeper: null, fielders: [] };
    if (l.role === "keeper") lineupsByMatch[l.match_id].keeper = l.player_id;
    else lineupsByMatch[l.match_id].fielders.push(l.player_id);
  });
  const feesByPlayer = {};
  feePayments.forEach((f) => {
    feesByPlayer[f.player_id] = feesByPlayer[f.player_id] || {};
    feesByPlayer[f.player_id][f.fee_type_id] = f.paid;
  });
  const statsByPlayer = {};
  players.forEach((p) => { statsByPlayer[p.id] = { goals: 0, assists: 0 }; });
  goals.forEach((g) => {
    if (statsByPlayer[g.scorer_id]) statsByPlayer[g.scorer_id].goals += 1;
    if (g.assist_id && statsByPlayer[g.assist_id]) statsByPlayer[g.assist_id].assists += 1;
  });
  const goalsByMatch = {};
  goals.forEach((g) => {
    goalsByMatch[g.match_id] = goalsByMatch[g.match_id] || [];
    goalsByMatch[g.match_id].push(g);
  });

  if (loading) {
    return (
      <div style={styles.app} className="tott-app dreelio-app">
        <style>{globalCss + dreelioDashboardCss + appFeelingCss + fcxMobileDashboardCss + kpiRectangleHardFixCss + spacingPolishCss + fullAppFcxThemeCss + readabilityFixCss + roleVideoCss + adminBeheerPolishCss + mobileZoomLockCss + publicLandingCss}</style>
        <div style={styles.loadingScreen}>Laden…</div>
      </div>
    );
  }

  if (loadError) {
    return (
      <div style={styles.app} className="tott-app dreelio-app">
        <style>{globalCss + dreelioDashboardCss + appFeelingCss + fcxMobileDashboardCss + kpiRectangleHardFixCss + spacingPolishCss + fullAppFcxThemeCss + readabilityFixCss + roleVideoCss + adminBeheerPolishCss + mobileZoomLockCss + publicLandingCss}</style>
        <div style={styles.loadingScreen}>
          <AlertCircle size={22} style={{ marginBottom: 10, color: "var(--warn)" }} />
          <div>Het clubportaal is tijdelijk niet bereikbaar.</div>
          <div style={{ fontSize: 12, color: "var(--text-dim)", marginTop: 8 }}>
            Probeer het later opnieuw of neem contact op met het bestuur.
          </div>
        </div>
      </div>
    );
  }

  if (route !== "portal") {
    const publicPosts = clubPosts.filter((post) => post.public_visible !== false);
    const publicVideos = matchVideos.filter((video) => video.public_visible !== false);
    return (
      <div className="public-site-shell">
        <style>{globalCss + dreelioDashboardCss + appFeelingCss + fcxMobileDashboardCss + kpiRectangleHardFixCss + spacingPolishCss + fullAppFcxThemeCss + readabilityFixCss + roleVideoCss + adminBeheerPolishCss + mobileZoomLockCss + publicLandingCss}</style>
        <PublicLanding
          branding={branding}
          matches={matches}
          posts={publicPosts}
          videos={publicVideos}
          sponsors={clubSponsors}
          goals={goals}
          onLoginClick={goToPortal}
          onSubmitFriendlyRequest={async (payload) => {
            await db.createFriendlyMatchRequest(payload);
            const next = await db.fetchFriendlyMatchRequests();
            setFriendlyRequests(next || []);
          }}
        />
      </div>
    );
  }

  if (!me) {
    return (
      <div style={styles.app} className="tott-app dreelio-app">
        <style>{globalCss + dreelioDashboardCss + appFeelingCss + fcxMobileDashboardCss + kpiRectangleHardFixCss + spacingPolishCss + fullAppFcxThemeCss + readabilityFixCss + roleVideoCss + adminBeheerPolishCss + mobileZoomLockCss + publicLandingCss}</style>
        <Header branding={branding} />
        <LoginScreen players={players} onLogin={login} branding={branding} />
        <footer style={styles.footer}>FC TOTT · Sponsored By Nola Marketing (website, branding en marketing)</footer>
      </div>
    );
  }

  const myOpenCount = isFinancialContributor(me) ? feeTypes.filter((f) => !(feesByPlayer[me.id] || {})[f.id]).length : 0;
  const potTotal = fines.reduce((sum, f) => sum + Number(f.amount), 0);

  return (
    <div style={styles.app} className="tott-app dreelio-app">
      <style>{globalCss + dreelioDashboardCss + appFeelingCss + fcxMobileDashboardCss + kpiRectangleHardFixCss + spacingPolishCss + fullAppFcxThemeCss + readabilityFixCss + roleVideoCss + adminBeheerPolishCss + mobileZoomLockCss + publicLandingCss}</style>

      <div className="dreelio-shell">
        <DreelioSidebar
          me={me}
          tab={tab}
          setTab={changeTab}
          onLogout={logout}
          myOpenCount={myOpenCount}
          potTotal={potTotal}
          postsCount={clubPosts.length}
          nextMatch={nextMatch}
          attendanceByMatch={attendanceByMatch}
          branding={branding}
          navItems={navItems}
        />

        <div className="dreelio-content">
          <div className="dreelio-mobile-topbar">
            <Header me={me} onLogout={logout} branding={branding} />
          </div>

          <main style={styles.main} className="tott-main dreelio-main" onTouchStart={handleSwipeStart} onTouchEnd={handleSwipeEnd}>
            {tab === "overzicht" && (
              <Top3
                nextMatch={nextMatch}
                countdown={countdown}
                myOpenCount={myOpenCount}
                potTotal={potTotal}
                me={me}
                players={players}
                attendanceByMatch={attendanceByMatch}
                setTab={changeTab}
                posts={clubPosts}
                branding={branding}
                statsByPlayer={statsByPlayer}
                feeTypes={feeTypes}
                feesByPlayer={feesByPlayer}
                notificationReads={notificationReads}
                onReadNotifications={markNotificationsRead}
              />
            )}
            {tab === "wedstrijden" && (
              <MatchesTab
                matches={matches} players={players}
                attendanceByMatch={attendanceByMatch} lineupsByMatch={lineupsByMatch}
                goalsByMatch={goalsByMatch}
                me={me} isAdmin={isAdmin} reloadAll={reloadAll}
              />
            )}
            {tab === "updates" && (
              <UpdatesTab
                posts={clubPosts}
                setPosts={syncClubPosts}
                me={me}
                players={players}
                isAdmin={isAdmin}
                canManageContent={canManageContent}
              />
            )}
            {tab === "videos" && (
              <VideosTab
                videos={matchVideos}
                setVideos={syncMatchVideos}
                matches={matches}
                me={me}
                isAdmin={isAdmin}
                canManageContent={canManageContent}
              />
            )}
            {tab === "profiel" && (
              <ProfileTab
                me={me} players={players}
                attendanceByMatch={attendanceByMatch} matches={matches}
                statsByPlayer={statsByPlayer} isAdmin={isAdmin} reloadAll={reloadAll} onLogout={logout}
              />
            )}
            {tab === "boetepot" && (
              <FinePotTab fineRules={fineRules} fines={fines} players={players} isAdmin={isAdmin} reloadAll={reloadAll} />
            )}
            {tab === "huisregels" && (
              <RulesTab rules={rules} isAdmin={isAdmin} reloadAll={reloadAll} />
            )}
            {tab === "financien" && (
              <FinanceTab players={players} feeTypes={feeTypes} feesByPlayer={feesByPlayer} me={me} isAdmin={isAdmin} reloadAll={reloadAll} />
            )}
            {tab === "beheer" && isAdmin && (
              <AdminPanel players={players} posts={clubPosts} setPosts={syncClubPosts} videos={matchVideos} setVideos={syncMatchVideos} sponsors={clubSponsors} requests={friendlyRequests} reloadAll={reloadAll} branding={branding} setBranding={syncBranding} />
            )}
          </main>

          <footer style={styles.footer} className="dreelio-footer">FC TOTT · Sponsored By Nola Marketing (website, branding en marketing)</footer>
        </div>
      </div>
    </div>
  );
}


// ============================================================

// Public Landing Page
// ============================================================
function PublicLanding({ branding = DEFAULT_BRANDING, matches = [], posts = [], videos = [], sponsors = [], goals = [], onLoginClick, onSubmitFriendlyRequest }) {
  const [request, setRequest] = useState({ teamName: "", contactName: "", email: "", phone: "", preferredDate: "", message: "" });
  const [requestStatus, setRequestStatus] = useState("");
  const [requestBusy, setRequestBusy] = useState(false);

  const logoUrl = branding.logoUrl || DEFAULT_BRANDING.logoUrl;
  const sortedMatches = [...matches].sort((a, b) => new Date(a.match_date) - new Date(b.match_date));
  const upcoming = sortedMatches.filter((m) => new Date(m.match_date).getTime() > Date.now());
  const past = sortedMatches.filter((m) => new Date(m.match_date).getTime() <= Date.now()).reverse();
  const nextMatch = upcoming[0];
  const latestResult = past.find((m) => m.own_score !== null && m.own_score !== undefined && m.opponent_score !== null && m.opponent_score !== undefined);
  const publicNews = posts.slice(0, 3);
  const publicSponsors = sponsors.length > 0 ? sponsors : [
    { id: "fallback-1", name: "JAKO", logo_url: "" },
    { id: "fallback-2", name: "voetbalshop.nl", logo_url: "" },
    { id: "fallback-3", name: "Panna Kool", logo_url: "" },
    { id: "fallback-4", name: "Topsport", logo_url: "" },
    { id: "fallback-5", name: "Futsal.nl", logo_url: "" },
  ];
  const newsFallback = [
    { id: "fallback-news-1", title: "Training in volle gang", text: "Voorbereiding op de laatste wedstrijden van het seizoen.", category: "Training", date: "17 mei 2025", images: [] },
    { id: "fallback-news-2", title: "Overwinning in topper!", text: "FC TOTT wint spannende wedstrijd van City Futsal.", category: "Wedstrijd", date: "11 mei 2025", images: [] },
    { id: "fallback-news-3", title: "Nieuwe speler verwelkomd", text: "Malek komt het team versterken komend seizoen.", category: "Nieuws", date: "9 mei 2025", images: [] },
  ];
  const newsItems = publicNews.length > 0 ? publicNews : newsFallback;

  const submitFriendly = async (event) => {
    event.preventDefault();
    setRequestStatus("");
    if (!request.teamName.trim() || !request.contactName.trim() || !request.email.trim()) {
      setRequestStatus("Vul minimaal teamnaam, contactpersoon en e-mail in.");
      return;
    }
    setRequestBusy(true);
    try {
      await onSubmitFriendlyRequest?.(request);
      setRequest({ teamName: "", contactName: "", email: "", phone: "", preferredDate: "", message: "" });
      setRequestStatus("Aanvraag ontvangen. We nemen zo snel mogelijk contact op.");
    } catch (err) {
      console.error(err);
      setRequestStatus("Aanvraag kon niet worden verzonden. Probeer het later opnieuw.");
    } finally {
      setRequestBusy(false);
    }
  };

  const hasNextMatch = !!nextMatch;
  const hasLatestResult = !!latestResult;
  const nextMatchDate = nextMatch ? new Date(nextMatch.match_date) : null;
  const nextDate = nextMatchDate ? nextMatchDate.toLocaleDateString("nl-NL", { weekday: "short", day: "numeric", month: "long", year: "numeric" }) : "Nog niet gepland";
  const nextTime = nextMatchDate ? nextMatchDate.toLocaleTimeString("nl-NL", { hour: "2-digit", minute: "2-digit" }) : "Tijd volgt";
  const latestDate = latestResult ? new Date(latestResult.match_date).toLocaleDateString("nl-NL", { day: "numeric", month: "long", year: "numeric" }) : "Nog geen wedstrijd gespeeld";
  const latestScore = latestResult ? `${latestResult.own_score} - ${latestResult.opponent_score}` : "—";
  const latestOpponent = latestResult?.opponent || "Tegenstander";
  const nextOpponent = nextMatch?.opponent || "Tegenstander volgt";
  const latestResultLabel = latestResult ? (Number(latestResult.own_score) > Number(latestResult.opponent_score) ? "Gewonnen" : Number(latestResult.own_score) === Number(latestResult.opponent_score) ? "Gelijk" : "Verloren") : "Nog geen uitslag";

  return (
    <div className="fcx-public" id="home">
      <header className="fcx-mobile-header">
        <a className="fcx-mobile-brand" href="#home" aria-label="FC Talk Of The Town home">
          <img src={logoUrl} alt="FC Talk Of The Town" />
          <span><strong>FC Talk Of The Town</strong><small>Futsal Club</small></span>
        </a>
        <div className="fcx-mobile-header-actions">
          <button className="fcx-login-pill" onClick={onLoginClick}><Users size={18} /> Log in</button>
          <button className="fcx-menu-btn" aria-label="Menu"><span /><span /><span /></button>
        </div>
      </header>

      <main className="fcx-mobile-page">
        <section className="fcx-mobile-hero">
          <div className="fcx-hero-copy">
            <h1>FC Talk Of <span>The Town</span></h1>
            <div className="fcx-hero-sub">Futsal. Community. Passie.</div>
            <p>Welkom bij FC Talk Of The Town Futsal Club. De thuisbasis voor supporters, nieuws, sponsoren en oefenwedstrijden aanvragen.</p>
            <div className="fcx-hero-actions">
              <a className="fcx-red-cta" href="#wedstrijden"><Calendar size={18} /> Bekijk volgende wedstrijd <ChevronRight size={18} /></a>
              <a className="fcx-gold-cta" href="#friendly"><Handshake size={18} /> Vraag oefenwedstrijd aan <ChevronRight size={18} /></a>
            </div>
          </div>
          <div className="fcx-hero-visual" aria-hidden="true">
            <img className="fcx-hero-watermark" src={logoUrl} alt="" />
            <div className="fcx-player-silhouette">
              <div className="fcx-player-head" />
              <div className="fcx-player-body"><span>Talk Of The Town</span><strong>10</strong></div>
              <div className="fcx-player-ball" />
            </div>
          </div>
        </section>

        <section id="wedstrijden" className="fcx-mobile-section fcx-match-section">
          <div className="fcx-match-section-head">
            <SectionTitle title="Alles rondom FC TOTT" />
            <p>De belangrijkste wedstrijdinformatie in één rustige clubkaart.</p>
          </div>

          <div className="fcx-match-grid">
            <article className={`fcx-match-card fcx-next-match-card ${!hasNextMatch ? "is-empty" : ""}`}>
              <div className="fcx-card-kicker"><Calendar size={15} /> Volgende wedstrijd</div>
              <div className="fcx-versus-row">
                <div className="fcx-team-badge-wrap">
                  <img src={logoUrl} alt="FC TOTT" />
                  <span>FC TOTT</span>
                </div>
                <div className="fcx-vs-pill">VS</div>
                <div className="fcx-team-badge-wrap">
                  <div className="fcx-opponent-badge">{nextOpponent.slice(0, 2).toUpperCase()}</div>
                  <span>{nextOpponent}</span>
                </div>
              </div>
              <div className="fcx-match-details-box">
                <div className="fcx-meta-line"><Calendar size={15} /> {nextDate}</div>
                <div className="fcx-meta-line"><Clock size={15} /> {nextTime}</div>
                <div className="fcx-meta-line"><MapPin size={15} /> {nextMatch?.location || "Locatie volgt"}</div>
              </div>
              <a className="fcx-card-action" href="/portal">Wedstrijd details <ChevronRight size={16} /></a>
            </article>

            <article className={`fcx-match-card fcx-result-card ${!hasLatestResult ? "is-empty" : ""}`}>
              <div className="fcx-card-kicker"><Trophy size={15} /> Laatste uitslag</div>
              <div className="fcx-score-showcase">
                <div className="fcx-team-badge-wrap compact">
                  <img src={logoUrl} alt="FC TOTT" />
                  <span>FC TOTT</span>
                </div>
                <strong>{latestScore}</strong>
                <div className="fcx-team-badge-wrap compact">
                  <div className="fcx-opponent-badge">{latestOpponent.slice(0, 2).toUpperCase()}</div>
                  <span>{latestOpponent}</span>
                </div>
              </div>
              <div className="fcx-match-details-box">
                <div className="fcx-meta-line"><Calendar size={15} /> {latestDate}</div>
                <div className={`fcx-result-pill ${!hasLatestResult ? "muted" : ""}`}>{latestResultLabel}</div>
              </div>
              <a className="fcx-card-action" href="/portal">Bekijk uitslagen <ChevronRight size={16} /></a>
            </article>
          </div>
        </section>

        <section id="team" className="fcx-mobile-section">
          <div className="fcx-section-headline"><SectionTitle title="Laatste updates" /><button onClick={onLoginClick}>Bekijk alle updates <ChevronRight size={16} /></button></div>
          <div className="fcx-news-row">
            {newsItems.map((post, index) => (
              <article className="fcx-news-card" key={post.id || index}>
                <div className={`fcx-news-thumb fcx-news-thumb-${index + 1}`}>
                  {post.images?.[0] ? <img src={post.images[0]} alt="" /> : <span>{(post.category || "Nieuws").slice(0, 9)}</span>}
                </div>
                <small>{post.date || (post.created_at ? formatDateShort(post.created_at) : "Clubnieuws")}</small>
                <h3>{post.title}</h3>
                <p>{post.text || post.body || "Meer nieuws verschijnt binnenkort in het clubportal."}</p>
              </article>
            ))}
          </div>
        </section>

        <section id="friendly" className="fcx-friendly-strip">
          <div className="fcx-handshake"><Handshake size={56} /></div>
          <div>
            <h2>Oefenwedstrijd aanvragen</h2>
            <p>Op zoek naar een sterke tegenstander? Vraag een oefenwedstrijd aan en we regelen zo snel mogelijk contact met je op.</p>
          </div>
          <a href="#friendly-form" className="fcx-gold-cta">Aanvraag versturen <ChevronRight size={18} /></a>
        </section>

        <section id="sponsors" className="fcx-mobile-section fcx-sponsors-section">
          <div className="fcx-section-headline"><SectionTitle title="Onze sponsors" /><a href="#contact">Partner worden <ChevronRight size={16} /></a></div>
          <div className="fcx-sponsor-row">
            {publicSponsors.map((sponsor) => (
              <a key={sponsor.id} className="fcx-sponsor-tile" href={sponsor.website_url || sponsor.websiteUrl || "#"} target={sponsor.website_url || sponsor.websiteUrl ? "_blank" : undefined} rel="noreferrer">
                {sponsor.logo_url ? <img src={sponsor.logo_url} alt={sponsor.name} /> : <span>{sponsor.name}</span>}
              </a>
            ))}
          </div>
        </section>

        <section className="fcx-mobile-section fcx-portal-section">
          <SectionTitle title="Toegang tot het portal" />
          {[{ title: "Spelers", icon: Users, text: "Bekijk wedstrijden, statistieken en teamupdates." }, { title: "Begeleiders", icon: ShieldCheck, text: "Beheer team, communicatie en wedstrijden." }, { title: "Admins", icon: Shield, text: "Volledige toegang tot clubbeheer & instellingen." }].map((item, index) => {
            const Icon = item.icon;
            return (
              <button className="fcx-portal-row" key={item.title} onClick={onLoginClick}>
                <Icon size={30} className={index === 1 ? "gold" : ""} />
                <span><strong>{item.title}</strong><small>{item.text}</small></span>
                <b>Log in <ChevronRight size={16} /></b>
              </button>
            );
          })}
        </section>

        <section id="contact" className="fcx-mobile-section fcx-contact-section">
          <SectionTitle title="Aanvraag versturen" />
          <form id="friendly-form" className="fcx-mobile-form" onSubmit={submitFriendly}>
            <input value={request.teamName} onChange={(e) => setRequest({ ...request, teamName: e.target.value })} placeholder="Teamnaam" />
            <input value={request.contactName} onChange={(e) => setRequest({ ...request, contactName: e.target.value })} placeholder="Contactpersoon" />
            <input type="email" value={request.email} onChange={(e) => setRequest({ ...request, email: e.target.value })} placeholder="E-mail" />
            <input value={request.phone} onChange={(e) => setRequest({ ...request, phone: e.target.value })} placeholder="Telefoon" />
            <input type="date" value={request.preferredDate} onChange={(e) => setRequest({ ...request, preferredDate: e.target.value })} />
            <textarea value={request.message} onChange={(e) => setRequest({ ...request, message: e.target.value })} placeholder="Bericht of voorkeuren" rows={4} />
            {requestStatus && <div className="fcx-public-form-status">{requestStatus}</div>}
            <button className="fcx-red-cta" disabled={requestBusy}>{requestBusy ? "Versturen…" : "Aanvraag versturen"} <ChevronRight size={18} /></button>
          </form>
        </section>
      </main>

      <footer className="fcx-mobile-footer">
        <div className="fcx-footer-brand"><img src={logoUrl} alt="FC TOTT" /><span><strong>FC Talk Of The Town</strong><small>Futsal. Community. Passie.</small></span></div>
        <div className="fcx-footer-contact"><span><MessageCircle size={15} /> info@fctalkofthetownfutsal.nl</span><span><MapPin size={15} /> Binnenweg 123, 1000 AA Amsterdam</span><span>☎ +31 6 12345678</span></div>
        <div className="fcx-footer-social"><strong>Volg ons</strong><span>◎ ● ▶ ♪</span></div>
        <small>© {new Date().getFullYear()} FC Talk Of The Town Futsal Club. Alle rechten voorbehouden.</small>
      </footer>
    </div>
  );
}

function SectionTitle({ title }) {
  return <div className="fcx-section-title"><span />{title}</div>;
}

// ============================================================
// Login
// ============================================================
function LoginScreen({ players, onLogin, branding = DEFAULT_BRANDING }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    setError("");
    try {
      const found = await db.findPlayerByCredentials(username, password);
      if (!found) {
        setError("Gebruikersnaam of wachtwoord klopt niet.");
        return;
      }
      if (!found.active) {
        setError("Dit account is door een beheerder geblokkeerd. Neem contact op met het bestuur.");
        return;
      }
      onLogin(found.id);
    } catch (err) {
      setError("Inloggen lukt nu niet. Probeer het later opnieuw of neem contact op met het bestuur.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={styles.loginWrap}>
      <form style={styles.loginCard} className="dreelio-login-card" onSubmit={submit}>
        {branding.loginBannerUrl && (
          <img src={branding.loginBannerUrl} alt="Clubbeeld" className="dreelio-login-banner" />
        )}
        <div style={styles.loginIcon}><Lock size={20} /></div>
        <div style={styles.loginTitle}>Inloggen bij FC TOTT</div>
        <div style={styles.loginSub}>Gebruik de inloggegevens die je van het bestuur hebt gekregen.</div>

        <label style={styles.loginLabel}>Gebruikersnaam</label>
        <input style={styles.input} value={username} onChange={(e) => setUsername(e.target.value)}
          autoComplete="username" placeholder="bijv. daan" />

        <label style={styles.loginLabel}>Wachtwoord</label>
        <div style={styles.pwRow}>
          <input style={{ ...styles.input, flex: 1 }} type={showPw ? "text" : "password"}
            value={password} onChange={(e) => setPassword(e.target.value)}
            autoComplete="current-password" placeholder="••••••" />
          <button type="button" style={styles.pwToggle} onClick={() => setShowPw((s) => !s)} aria-label="Wachtwoord tonen">
            {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
          </button>
        </div>

        {error && <div style={styles.loginError}><AlertCircle size={14} /> {error}</div>}

        <button type="submit" style={styles.primaryBtnFull} disabled={busy}>
          {busy ? "Bezig…" : "Inloggen"}
        </button>
      </form>
    </div>
  );
}

