function RulesTab({ rules, isAdmin, reloadAll }) {
  const [newRule, setNewRule] = useState("");
  const [busy, setBusy] = useState(false);

  const addRule = async () => {
    if (!newRule.trim()) return;
    setBusy(true);
    try {
      await db.addRule(newRule.trim(), rules.length + 1);
      await reloadAll();
      setNewRule("");
    } finally { setBusy(false); }
  };
  const removeRule = async (id) => {
    setBusy(true);
    try { await db.deleteRule(id); await reloadAll(); } finally { setBusy(false); }
  };

  return (
    <section>
      <div style={styles.sectionHead} className="tott-sectionhead">
        <div>
          <div style={styles.eyebrow}>Afspraken</div>
          <h2 style={styles.h2} className="tott-h2">Huisregels</h2>
        </div>
      </div>
      <div style={styles.rulesCard} className="dreelio-panel dreelio-rules-card">
        {rules.map((r, i) => (
          <div key={r.id} style={styles.ruleRow}>
            <span style={styles.ruleNum}>{String(i + 1).padStart(2, "0")}</span>
            <span style={styles.ruleText}>{r.text}</span>
            {isAdmin && (
              <button style={styles.iconBtnGhost} onClick={() => removeRule(r.id)} aria-label="Verwijderen"><X size={14} /></button>
            )}
          </div>
        ))}
        {rules.length === 0 && <EmptyState text="Nog geen huisregels toegevoegd." dark />}
      </div>
      {isAdmin && (
        <div style={styles.addRuleRow} className="tott-addrow dreelio-panel dreelio-add-row">
          <input style={styles.input} placeholder="Nieuwe huisregel toevoegen…" value={newRule}
            onChange={(e) => setNewRule(e.target.value)} onKeyDown={(e) => e.key === "Enter" && addRule()} />
          <button style={styles.primaryBtn} onClick={addRule} disabled={busy}><Plus size={15} /> Toevoegen</button>
        </div>
      )}
    </section>
  );
}


// ============================================================
// Video's
// ============================================================
function VideosTab({ videos, setVideos, matches = [], me, isAdmin, canManageContent }) {
  const [showForm, setShowForm] = useState(videos.length === 0 && canManageContent);
  const [draft, setDraft] = useState({ title: "", youtubeUrl: "", matchId: "", description: "" });
  const [activeVideoId, setActiveVideoId] = useState(videos[0]?.id || null);
  const [videoError, setVideoError] = useState("");

  const sortedVideos = [...videos].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
  const activeVideo = sortedVideos.find((video) => video.id === activeVideoId) || sortedVideos[0];

  const addVideo = () => {
    if (!canManageContent) return;
    const youtubeUrl = draft.youtubeUrl.trim();
    const embedUrl = getYouTubeEmbedUrl(youtubeUrl);
    if (!embedUrl) {
      setVideoError("Plak een geldige YouTube-link, bijvoorbeeld een youtu.be of youtube.com link.");
      return;
    }
    setVideoError("");
    const match = matches.find((m) => m.id === draft.matchId);
    const video = {
      id: makeVideoId(),
      title: draft.title.trim() || (match ? `FC TOTT vs ${match.opponent}` : "Wedstrijdvideo"),
      youtubeUrl,
      match_id: draft.matchId || "",
      match_label: match ? `FC TOTT vs ${match.opponent} · ${formatDateShort(match.match_date)}` : "Losse wedstrijdvideo",
      description: draft.description.trim(),
      author_id: me?.id,
      author_name: me?.name,
      created_at: new Date().toISOString(),
    };
    const next = [video, ...videos];
    setVideos(next);
    setActiveVideoId(video.id);
    setDraft({ title: "", youtubeUrl: "", matchId: "", description: "" });
    setShowForm(false);
  };

  const removeVideo = (id) => {
    if (!isAdmin) return;
    if (!window.confirm("Weet je zeker dat je deze video wilt verwijderen?")) return;
    const next = videos.filter((video) => video.id !== id);
    setVideos(next);
    if (activeVideoId === id) setActiveVideoId(next[0]?.id || null);
  };

  return (
    <section className="dreelio-videos-page">
      <div style={styles.sectionHead} className="tott-sectionhead">
        <div>
          <div style={styles.eyebrow}>Wedstrijdbeelden</div>
          <h2 style={styles.h2} className="tott-h2">Video's</h2>
        </div>
        {canManageContent && (
          <button style={styles.addBtn} onClick={() => setShowForm((open) => !open)} type="button">
            <Plus size={15} /> {showForm ? "Sluiten" : "Video toevoegen"}
          </button>
        )}
      </div>

      <div className="dreelio-muted-note dreelio-updates-note">
        Kijk volledige wedstrijdbeelden terug via een unieke YouTube-link. De video zelf staat niet in het clubportaal.
      </div>

      {canManageContent && showForm && (
        <div className="dreelio-panel dreelio-video-form">
          <div style={styles.formRow} className="tott-formrow">
            <input style={styles.input} placeholder="Titel, bijv. FC TOTT vs FC Urban" value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} />
            <select style={styles.input} value={draft.matchId} onChange={(e) => setDraft({ ...draft, matchId: e.target.value })}>
              <option value="">Koppel aan wedstrijd…</option>
              {matches.map((m) => <option key={m.id} value={m.id}>FC TOTT vs {m.opponent} · {formatDateShort(m.match_date)}</option>)}
            </select>
          </div>
          <input style={styles.input} placeholder="YouTube-link, bijvoorbeeld https://youtu.be/..." value={draft.youtubeUrl} onChange={(e) => setDraft({ ...draft, youtubeUrl: e.target.value })} />
          <textarea style={styles.textarea} rows={3} placeholder="Korte beschrijving of aandachtspunten…" value={draft.description} onChange={(e) => setDraft({ ...draft, description: e.target.value })} />
          {videoError && <div className="dreelio-admin-error"><AlertCircle size={14} /> {videoError}</div>}
          <button style={styles.primaryBtn} onClick={addVideo} type="button"><PlayCircle size={15} /> Video opslaan</button>
        </div>
      )}

      {sortedVideos.length === 0 ? (
        <div className="dreelio-panel dreelio-video-empty">
          <Video size={28} />
          <h3>Nog geen wedstrijdvideo's</h3>
          <p>Zodra het bestuur of een begeleider een YouTube-link toevoegt, kun je de wedstrijd hier terugkijken.</p>
        </div>
      ) : (
        <div className="dreelio-video-layout">
          <div className="dreelio-panel dreelio-video-player-card">
            <div className="dreelio-video-frame">
              {activeVideo && <iframe src={getYouTubeEmbedUrl(activeVideo.youtubeUrl)} title={activeVideo.title} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen />}
            </div>
            <div className="dreelio-video-player-copy">
              <span>{activeVideo?.match_label}</span>
              <h3>{activeVideo?.title}</h3>
              {activeVideo?.description && <p>{activeVideo.description}</p>}
              {activeVideo?.youtubeUrl && <a href={activeVideo.youtubeUrl} target="_blank" rel="noreferrer"><ExternalLink size={14} /> Open op YouTube</a>}
            </div>
          </div>

          <div className="dreelio-video-list">
            {sortedVideos.map((video) => (
              <button key={video.id} type="button" className={`dreelio-video-row ${activeVideo?.id === video.id ? "is-active" : ""}`} onClick={() => setActiveVideoId(video.id)}>
                <span className="dreelio-video-thumb"><PlayCircle size={22} /></span>
                <span className="dreelio-video-row-copy">
                  <strong>{video.title}</strong>
                  <small>{video.match_label}</small>
                </span>
                {isAdmin && <span className="dreelio-video-delete" onClick={(e) => { e.stopPropagation(); removeVideo(video.id); }}><Trash2 size={14} /></span>}
              </button>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

// ============================================================
// Financiën
// ============================================================
function FinanceTab({ players, feeTypes, feesByPlayer, me, isAdmin, reloadAll }) {
  const [showAll, setShowAll] = useState(false);
  const [busy, setBusy] = useState(false);
  const contributionPlayers = players.filter(isFinancialContributor);
  const isBegeleider = me?.role === "begeleider";

  const toggleFee = async (playerId, feeTypeId, current) => {
    if (!isAdmin) return;
    setBusy(true);
    try { await db.toggleFeePayment(playerId, feeTypeId, !current); await reloadAll(); } finally { setBusy(false); }
  };

  return (
    <section>
      <div style={styles.meCard} className="dreelio-panel dreelio-me-card">
        <div style={styles.meCardTitle}>{isBegeleider ? "Financiën voor begeleiders" : `Jouw betalingen, ${me.name.split(" ")[0]}`}</div>
        {isBegeleider ? (
          <div className="dreelio-muted-note">Begeleiders hoeven niet bij te dragen aan spelersbetalingen. Je kunt dit tabblad wel bekijken voor teamoverzicht.</div>
        ) : (
          <div style={styles.myFeeList}>
            {feeTypes.map((f) => {
              const Icon = FEE_ICONS[f.id] || Wallet;
              const paid = !!(feesByPlayer[me.id] || {})[f.id];
              return (
                <div key={f.id} style={styles.myFeeRow}>
                  <span style={styles.myFeeName}><Icon size={16} /> {f.label} <span style={styles.legendAmount}>€{f.amount}</span></span>
                  <span style={{ ...styles.statusPill, ...(paid ? styles.pillPaid : styles.pillOpen) }}>
                    {paid ? <Check size={13} /> : <X size={13} />}
                    {paid ? "Voldaan" : "Open"}
                  </span>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div style={styles.sectionHead} className="tott-sectionhead">
        <div>
          <div style={styles.eyebrow}>Betalingen</div>
          <h2 style={styles.h2} className="tott-h2">Financiën</h2>
        </div>
      </div>

      <button style={styles.attendanceToggle} onClick={() => setShowAll((s) => !s)}>
        <span style={styles.attendanceToggleLabel}>Iedereen bekijken {showAll ? <ChevronUp size={14} /> : <ChevronDown size={14} />}</span>
      </button>

      {showAll && (
        <div style={styles.tableWrap} className="dreelio-panel dreelio-table-wrap">
          <table style={styles.table} className="tott-finance-table">
            <thead>
              <tr>
                <th style={styles.thName}>Speler</th>
                {feeTypes.map((f) => <th key={f.id} style={styles.th}>{f.label}</th>)}
              </tr>
            </thead>
            <tbody>
              {contributionPlayers.map((p) => {
                const pf = feesByPlayer[p.id] || {};
                const openForPlayer = feeTypes.filter((f) => !pf[f.id]).length;
                return (
                  <tr key={p.id} style={styles.tr}>
                    <td style={styles.tdName} className="tott-finance-row-name">
                      {p.name}
                      {openForPlayer > 0 && <span style={styles.warnBadge}><AlertCircle size={11} /> {openForPlayer} open</span>}
                    </td>
                    {feeTypes.map((f) => {
                      const paid = !!pf[f.id];
                      return (
                        <td key={f.id} style={styles.td} className="tott-finance-cell" data-label={f.label}>
                          <button onClick={() => toggleFee(p.id, f.id, paid)} disabled={!isAdmin || busy}
                            style={{ ...styles.statusPill, ...(paid ? styles.pillPaid : styles.pillOpen), ...(isAdmin ? {} : { opacity: 0.85, cursor: "default" }) }}
                            className="tott-pill">
                            {paid ? <Check size={13} /> : <X size={13} />}
                            {paid ? "Voldaan" : "Open"}
                          </button>
                        </td>
                      );
                    })}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

// ============================================================
// Admin panel: user management
// ============================================================
function AdminPanel({ players, posts = [], setPosts, videos = [], setVideos, sponsors = [], requests = [], reloadAll, branding = DEFAULT_BRANDING, setBranding }) {
  const [section, setSection] = useState("spelers");
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("iedereen");
  const [newPlayer, setNewPlayer] = useState({ name: "", username: "", password: "", role: "speler" });
  const [newSponsor, setNewSponsor] = useState({ name: "", logo_url: "", website_url: "", description: "", sort_order: 100 });
  const [playerEdits, setPlayerEdits] = useState({});
  const [brandingDraft, setBrandingDraft] = useState(branding);
  const [busy, setBusy] = useState(false);
  const [adminError, setAdminError] = useState("");
  const [adminSuccess, setAdminSuccess] = useState("");

  useEffect(() => {
    setBrandingDraft(branding);
  }, [branding]);

  const getEdit = (player) => playerEdits[player.id] || {
    name: player.name || "",
    username: player.username || "",
    photo: player.photo || "",
    position: player.position || "Allround",
    number: player.number || "",
    role: player.role || "speler",
    password: "",
  };

  const updateEdit = (player, patch) => {
    setPlayerEdits((cur) => ({ ...cur, [player.id]: { ...getEdit(player), ...patch } }));
  };

  const runAdminAction = async (action, successText) => {
    setBusy(true);
    setAdminError("");
    setAdminSuccess("");
    try {
      await action();
      if (successText) setAdminSuccess(successText);
    } catch (err) {
      console.error(err);
      setAdminError("Actie kon niet worden uitgevoerd. Controleer de gegevens en probeer opnieuw.");
    } finally {
      setBusy(false);
    }
  };

  const toggleActive = async (player) => {
    const nextActive = !player.active;
    if (!nextActive && !window.confirm(`Weet je zeker dat je ${player.name} wilt blokkeren?`)) return;
    await runAdminAction(async () => {
      await db.setPlayerActive(player.id, nextActive);
      await reloadAll();
    }, nextActive ? "Account is weer actief." : "Account is geblokkeerd.");
  };

  const removePlayer = async (player) => {
    if (!window.confirm(`Weet je zeker dat je ${player.name} definitief wilt verwijderen? Gebruik liever blokkeren als je twijfelt.`)) return;
    await runAdminAction(async () => {
      await db.deletePlayer(player.id);
      await reloadAll();
    }, "Speler is verwijderd.");
  };

  const savePlayer = async (player) => {
    const edit = getEdit(player);
    await runAdminAction(async () => {
      const payload = {
        name: edit.name.trim(),
        username: edit.username.trim(),
        photo: edit.photo.trim(),
        position: edit.position,
        number: Number(edit.number) || null,
        role: edit.role,
      };
      if (edit.password.trim()) payload.password = edit.password.trim();
      await db.updatePlayer(player.id, payload);
      await reloadAll();
      setPlayerEdits((cur) => {
        const next = { ...cur };
        delete next[player.id];
        return next;
      });
    }, "Speler is bijgewerkt.");
  };

  const saveBranding = () => {
    setBranding?.({ ...DEFAULT_BRANDING, ...brandingDraft });
    setAdminSuccess("Branding is lokaal opgeslagen.");
  };

  const addPlayer = async () => {
    if (!newPlayer.name.trim() || !newPlayer.username.trim() || !newPlayer.password.trim()) {
      setAdminError("Vul naam, gebruikersnaam en wachtwoord in.");
      return;
    }
    await runAdminAction(async () => {
      const exists = await db.usernameExists(newPlayer.username.trim());
      if (exists) throw new Error("username_exists");
      await db.createPlayer({
        name: newPlayer.name.trim(),
        username: newPlayer.username.trim(),
        password: newPlayer.password,
        role: newPlayer.role,
      });
      await reloadAll();
      setNewPlayer({ name: "", username: "", password: "", role: "speler" });
    }, "Account is aangemaakt.");
  };

  const filteredPlayers = players.filter((player) => {
    const q = query.trim().toLowerCase();
    const matchesQuery = !q || `${player.name || ""} ${player.username || ""}`.toLowerCase().includes(q);
    const matchesFilter =
      filter === "iedereen" ||
      (filter === "admins" && player.role === "admin") ||
      (filter === "begeleiders" && player.role === "begeleider") ||
      (filter === "spelers" && (!player.role || player.role === "speler")) ||
      (filter === "actief" && player.active !== false) ||
      (filter === "geblokkeerd" && player.active === false);
    return matchesQuery && matchesFilter;
  });

  const removeAdminPost = (post) => {
    if (!window.confirm("Weet je zeker dat je deze update wilt verwijderen?")) return;
    setPosts?.(posts.filter((item) => item.id !== post.id));
  };

  const toggleAdminPostPin = (post) => {
    setPosts?.(posts.map((item) => item.id === post.id ? { ...item, pinned: !item.pinned } : item));
  };

  const removeAdminVideo = (video) => {
    if (!window.confirm("Weet je zeker dat je deze video wilt verwijderen?")) return;
    setVideos?.(videos.filter((item) => item.id !== video.id));
  };


  const addSponsorNow = async () => {
    if (!newSponsor.name.trim()) {
      setAdminError("Vul minimaal de sponsornaam in.");
      return;
    }
    await runAdminAction(async () => {
      await db.addClubSponsor(newSponsor);
      await reloadAll();
      setNewSponsor({ name: "", logo_url: "", website_url: "", description: "", sort_order: 100 });
    }, "Sponsor is toegevoegd.");
  };

  const removeSponsorNow = async (sponsor) => {
    if (!window.confirm(`Weet je zeker dat je ${sponsor.name} wilt verwijderen?`)) return;
    await runAdminAction(async () => {
      await db.deleteClubSponsor(sponsor.id);
      await reloadAll();
    }, "Sponsor is verwijderd.");
  };

  const updateRequestStatus = async (request, status) => {
    await runAdminAction(async () => {
      await db.updateFriendlyMatchRequestStatus(request.id, status);
      await reloadAll();
    }, "Aanvraag is bijgewerkt.");
  };

  const removeRequestNow = async (request) => {
    if (!window.confirm("Weet je zeker dat je deze aanvraag wilt verwijderen?")) return;
    await runAdminAction(async () => {
      await db.deleteFriendlyMatchRequest(request.id);
      await reloadAll();
    }, "Aanvraag is verwijderd.");
  };

  const sections = [
    { key: "spelers", label: "Spelers", icon: Users },
    { key: "accounts", label: "Accounts", icon: UserPlus },
    { key: "branding", label: "Branding", icon: Camera },
    { key: "updates", label: "Updates", icon: Newspaper },
    { key: "videos", label: "Video's", icon: Video },
    { key: "sponsors", label: "Sponsors", icon: Star },
    { key: "requests", label: "Aanvragen", icon: Handshake },
  ];

  return (
    <section className="dreelio-admin-page">
      <div style={styles.sectionHead} className="tott-sectionhead">
        <div>
          <div style={styles.eyebrow}>Bestuur</div>
          <h2 style={styles.h2} className="tott-h2">Beheer</h2>
        </div>
      </div>

      <div className="dreelio-admin-stats">
        <div className="dreelio-admin-stat"><span>Spelers</span><strong>{players.length}</strong></div>
        <div className="dreelio-admin-stat"><span>Admins</span><strong>{players.filter((p) => p.role === "admin").length}</strong></div>
        <div className="dreelio-admin-stat"><span>Begeleiders</span><strong>{players.filter((p) => p.role === "begeleider").length}</strong></div>
        <div className="dreelio-admin-stat"><span>Geblokkeerd</span><strong>{players.filter((p) => p.active === false).length}</strong></div>
      </div>

      <div className="dreelio-admin-tabs">
        {sections.map((item) => {
          const Icon = item.icon;
          return (
            <button key={item.key} type="button" onClick={() => setSection(item.key)} className={section === item.key ? "is-active" : ""}>
              <Icon size={15} /> {item.label}
            </button>
          );
        })}
      </div>

      {adminError && <div className="dreelio-admin-error"><AlertCircle size={14} /> {adminError}</div>}
      {adminSuccess && <div className="dreelio-admin-success"><Check size={14} /> {adminSuccess}</div>}

      {section === "spelers" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div className="dreelio-admin-tools">
            <input style={styles.input} placeholder="Zoek speler of gebruikersnaam…" value={query} onChange={(e) => setQuery(e.target.value)} />
            <select style={styles.input} value={filter} onChange={(e) => setFilter(e.target.value)}>
              <option value="iedereen">Iedereen</option>
              <option value="spelers">Spelers</option>
              <option value="begeleiders">Begeleiders</option>
              <option value="admins">Admins</option>
              <option value="actief">Actief</option>
              <option value="geblokkeerd">Geblokkeerd</option>
            </select>
          </div>

          <div className="dreelio-admin-player-list">
            {filteredPlayers.map((player) => {
              const edit = getEdit(player);
              return (
                <div key={player.id} className="dreelio-admin-player-card">
                  <div className="dreelio-admin-player-head">
                    <div className="dreelio-admin-player-avatar">{edit.photo ? <img src={edit.photo} alt={edit.name} /> : (edit.name || "?").slice(0, 2).toUpperCase()}</div>
                    <div>
                      <strong>{player.name}</strong>
                      <span>@{player.username} · {roleLabel(player.role)} · {player.active === false ? "Geblokkeerd" : "Actief"}</span>
                    </div>
                  </div>

                  <div className="dreelio-admin-edit-grid">
                    <input style={styles.input} value={edit.name} onChange={(e) => updateEdit(player, { name: e.target.value })} placeholder="Naam" />
                    <input style={styles.input} value={edit.username} onChange={(e) => updateEdit(player, { username: e.target.value })} placeholder="Gebruikersnaam" />
                    <select style={styles.input} value={edit.role} onChange={(e) => updateEdit(player, { role: e.target.value })}>
                      <option value="speler">Speler</option>
                      <option value="begeleider">Begeleider</option>
                      <option value="admin">Admin</option>
                    </select>
                    <select style={styles.input} value={edit.position} onChange={(e) => updateEdit(player, { position: e.target.value })}>
                      {POSITIONS.map((pos) => <option key={pos} value={pos}>{pos}</option>)}
                    </select>
                    <input style={styles.input} type="number" min="1" max="99" value={edit.number || ""} onChange={(e) => updateEdit(player, { number: e.target.value })} placeholder="Rugnummer" />
                    <input style={styles.input} value={edit.photo} onChange={(e) => updateEdit(player, { photo: e.target.value })} placeholder="Profielfoto URL" />
                    <input style={styles.input} value={edit.password} onChange={(e) => updateEdit(player, { password: e.target.value })} placeholder="Nieuw wachtwoord optioneel" />
                  </div>

                  <div className="dreelio-admin-actions">
                    <button type="button" style={styles.primaryBtn} onClick={() => savePlayer(player)} disabled={busy}><Check size={14} /> Opslaan</button>
                    <button type="button" style={styles.secondaryBtn} onClick={() => toggleActive(player)} disabled={busy}>{player.active === false ? <><UserPlus size={14} /> Activeren</> : <><UserMinus size={14} /> Blokkeren</>}</button>
                    <button type="button" className="dreelio-danger-button" onClick={() => removePlayer(player)} disabled={busy}><Trash2 size={14} /> Verwijderen</button>
                  </div>
                </div>
              );
            })}
            {filteredPlayers.length === 0 && <EmptyState text="Geen spelers gevonden." />}
          </div>
        </div>
      )}

      {section === "accounts" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div style={styles.h3}>Nieuw account aanmaken</div>
          <div style={styles.formRow} className="tott-formrow">
            <input style={styles.input} placeholder="Volledige naam" value={newPlayer.name} onChange={(e) => setNewPlayer({ ...newPlayer, name: e.target.value })} />
            <input style={styles.input} placeholder="Gebruikersnaam" value={newPlayer.username} onChange={(e) => setNewPlayer({ ...newPlayer, username: e.target.value })} />
          </div>
          <div style={styles.formRow} className="tott-formrow">
            <input style={styles.input} placeholder="Wachtwoord" value={newPlayer.password} onChange={(e) => setNewPlayer({ ...newPlayer, password: e.target.value })} />
            <select style={styles.input} value={newPlayer.role} onChange={(e) => setNewPlayer({ ...newPlayer, role: e.target.value })}>
              <option value="speler">Speler</option>
              <option value="begeleider">Begeleider</option>
              <option value="admin">Admin</option>
            </select>
          </div>
          <div className="dreelio-muted-note">Begeleiders kunnen updates en video's plaatsen, maar tellen niet mee bij spelersbetalingen.</div>
          <button style={styles.primaryBtn} onClick={addPlayer} disabled={busy}><UserPlus size={15} /> Account aanmaken</button>
        </div>
      )}

      {section === "branding" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div style={styles.h3}>Clubbranding</div>
          <label style={styles.loginLabel}>Clublogo URL</label>
          <input style={styles.input} value={brandingDraft.logoUrl || ""} onChange={(e) => setBrandingDraft({ ...brandingDraft, logoUrl: e.target.value })} placeholder="Logo URL of data image" />
          <label style={styles.loginLabel}>Dashboard banner URL</label>
          <input style={styles.input} value={brandingDraft.bannerUrl || ""} onChange={(e) => setBrandingDraft({ ...brandingDraft, bannerUrl: e.target.value })} placeholder="Optionele bannerafbeelding" />
          <label style={styles.loginLabel}>Sponsorregel</label>
          <input style={styles.input} value={brandingDraft.sponsorText || ""} onChange={(e) => setBrandingDraft({ ...brandingDraft, sponsorText: e.target.value })} placeholder="Sponsorregel" />
          <button style={styles.primaryBtn} onClick={saveBranding} type="button"><Check size={15} /> Branding opslaan</button>
        </div>
      )}

      {section === "updates" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div style={styles.h3}>Updates beheren</div>
          <div className="dreelio-admin-list">
            {posts.length === 0 && <EmptyState text="Nog geen updates." />}
            {posts.map((post) => (
              <div key={post.id} className="dreelio-admin-list-row">
                <div><strong>{post.title}</strong><span>{post.category} · {post.author_name || "Team"} · {post.public_visible === false ? "Privé" : "Publiek"}</span></div>
                <button type="button" style={styles.secondaryBtn} onClick={() => setPosts?.(posts.map((item) => item.id === post.id ? { ...item, public_visible: item.public_visible === false } : item))}>{post.public_visible === false ? "Publiek maken" : "Privé maken"}</button>
                <button type="button" style={styles.secondaryBtn} onClick={() => toggleAdminPostPin(post)}>{post.pinned ? "Losmaken" : "Vastzetten"}</button>
                <button type="button" className="dreelio-danger-button" onClick={() => removeAdminPost(post)}><Trash2 size={14} /> Verwijderen</button>
              </div>
            ))}
          </div>
        </div>
      )}

      {section === "videos" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div style={styles.h3}>Video's beheren</div>
          <div className="dreelio-admin-list">
            {videos.length === 0 && <EmptyState text="Nog geen video's." />}
            {videos.map((video) => (
              <div key={video.id} className="dreelio-admin-list-row">
                <div><strong>{video.title}</strong><span>{video.match_label} · {video.public_visible === false ? "Privé" : "Publiek"}</span></div>
                <button type="button" style={styles.secondaryBtn} onClick={() => setVideos?.(videos.map((item) => item.id === video.id ? { ...item, public_visible: item.public_visible === false } : item))}>{video.public_visible === false ? "Publiek maken" : "Privé maken"}</button>
                <a href={video.youtubeUrl} target="_blank" rel="noreferrer" className="dreelio-admin-link"><ExternalLink size={14} /> Openen</a>
                <button type="button" className="dreelio-danger-button" onClick={() => removeAdminVideo(video)}><Trash2 size={14} /> Verwijderen</button>
              </div>
            ))}
          </div>
        </div>
      )}


      {section === "sponsors" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div style={styles.h3}>Sponsors beheren</div>
          <div style={styles.formRow} className="tott-formrow">
            <input style={styles.input} placeholder="Sponsornaam" value={newSponsor.name} onChange={(e) => setNewSponsor({ ...newSponsor, name: e.target.value })} />
            <input style={styles.input} placeholder="Logo URL" value={newSponsor.logo_url} onChange={(e) => setNewSponsor({ ...newSponsor, logo_url: e.target.value })} />
          </div>
          <div style={styles.formRow} className="tott-formrow">
            <input style={styles.input} placeholder="Website URL" value={newSponsor.website_url} onChange={(e) => setNewSponsor({ ...newSponsor, website_url: e.target.value })} />
            <input style={styles.input} type="number" placeholder="Volgorde" value={newSponsor.sort_order} onChange={(e) => setNewSponsor({ ...newSponsor, sort_order: e.target.value })} />
          </div>
          <input style={styles.input} placeholder="Korte omschrijving" value={newSponsor.description} onChange={(e) => setNewSponsor({ ...newSponsor, description: e.target.value })} />
          <button style={styles.primaryBtn} onClick={addSponsorNow} disabled={busy}><Plus size={15} /> Sponsor toevoegen</button>
          <div className="dreelio-admin-list" style={{ marginTop: 16 }}>
            {sponsors.length === 0 && <EmptyState text="Nog geen sponsors." />}
            {sponsors.map((sponsor) => (
              <div key={sponsor.id} className="dreelio-admin-list-row">
                <div><strong>{sponsor.name}</strong><span>{sponsor.website_url || "Geen website"}</span></div>
                {sponsor.website_url && <a href={sponsor.website_url} target="_blank" rel="noreferrer" className="dreelio-admin-link"><ExternalLink size={14} /> Openen</a>}
                <button type="button" className="dreelio-danger-button" onClick={() => removeSponsorNow(sponsor)}><Trash2 size={14} /> Verwijderen</button>
              </div>
            ))}
          </div>
        </div>
      )}

      {section === "requests" && (
        <div className="dreelio-panel dreelio-admin-block">
          <div style={styles.h3}>Oefenwedstrijd aanvragen</div>
          <div className="dreelio-admin-list">
            {requests.length === 0 && <EmptyState text="Nog geen aanvragen." />}
            {requests.map((request) => (
              <div key={request.id} className="dreelio-admin-list-row dreelio-request-row">
                <div>
                  <strong>{request.team_name || "Onbekend team"}</strong>
                  <span>{request.contact_name} · {request.email} {request.phone ? `· ${request.phone}` : ""}</span>
                  {request.preferred_date && <span>Voorkeursdatum: {request.preferred_date}</span>}
                  {request.message && <span>{request.message}</span>}
                </div>
                <select style={styles.input} value={request.status || "nieuw"} onChange={(e) => updateRequestStatus(request, e.target.value)}>
                  <option value="nieuw">Nieuw</option>
                  <option value="contact_opgenomen">Contact opgenomen</option>
                  <option value="ingepland">Ingepland</option>
                  <option value="afgewezen">Afgewezen</option>
                </select>
                <button type="button" className="dreelio-danger-button" onClick={() => removeRequestNow(request)}><Trash2 size={14} /> Verwijderen</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

function EmptyState({ text, dark = false }) {
  return (
    <div style={{ ...styles.empty, ...(dark ? { color: "var(--text-dim)" } : {}) }}>
      <ChevronRight size={14} style={{ opacity: 0.5 }} />
      {text}
    </div>
  );
}

